1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<title>Interviewer model evals</title>
6	<style>
7	  body { font: 14px/1.5 system-ui, sans-serif; margin: 16px; max-width: 960px; }
8	  pre { white-space: pre-wrap; background: #f4f4f4; padding: 8px; }
