12	<body>
13	<h1>Interviewer model evals</h1>
14	<p class="meta">
15	  Runs the interviewer prompt suite against an in-browser model.
16	  Query params: <code>model</code> (default <code>onnx-community/gemma-3-1b-it-ONNX</code>),
17	  <code>dtype</code> (default <code>q4</code>), <code>suite</code> (<code>baseline</code>, <code>guided</code> or <code>all</code>).
18	  Results land in <code>window.results</code> and can be saved as JSON.
19	</p>
20	<div id="status">starting</div>
21	<button id="save" disabled>Save results as JSON</button>
22	<div id="out"></div>
23	
24	<script type="module">
25	import { pipeline } from 'https://cdn.jsdelivr.net/npm/@huggingface/transformers@4.3.0';
26	
27	const params = new URLSearchParams(location.search);
28	const MODEL = params.get('model') ?? 'onnx-community/gemma-3-1b-it-ONNX';
29	const DTYPE = params.get('dtype') ?? 'q4';
30	const SUITE = params.get('suite') ?? 'all';
31	
32	const out = document.getElementById('out');
33	const status = (s) => { document.getElementById('status').textContent = s; window.evalStatus = s; };
34	window.results = [];
35	
36	// ---------------------------------------------------------------------------
37	// Fixtures: questions and candidate answers of known quality.
38	// ---------------------------------------------------------------------------
39	const Q = {
40	  pressure: 'Tell me about a time you had to solve a problem under pressure.',
41	  improved: 'Tell me about a time you improved something that was not working well.',
42	  useEffect: 'Can you explain what the useEffect hook does in React and when you would use it?',
43	  leaving: 'Why do you want to leave your current job?',
44	};
45	const A = {
46	  rambling: `Um, so basically there was this time at my internship where, like, the build was broken, and you know, everyone was kind of stressed, and I basically just, um, looked at it and stuff and then it was fixed I guess. It was fine.`,
47	  starGood: `In my final year project our React app took 9 seconds to load on mobile. I was responsible for the frontend, so I owned fixing it. I profiled it with Lighthouse, found a 2 MB chart library loaded on every page, lazy loaded it and split the routes. Load time dropped to 2.1 seconds and our demo day score went up.`,
48	  we: `So our team had a really slow dashboard, and we decided to rewrite the data layer. We moved to React Query and we added caching, and we also cleaned up a lot of the components. In the end the dashboard was much faster and the client was happy.`,
49	  short: `I fixed a bug once that was urgent.`,
50	  techPartial: `useEffect is for side effects, like fetching data when the component loads. You put the fetch inside it and it runs after render.`,
51	  hr: `Honestly the pay is low and my manager is not great, and there is not much learning anymore.`,
52	};
53	
54	// ---------------------------------------------------------------------------
55	// Prompts under test (the guided versions are what the app will use).
56	// ---------------------------------------------------------------------------
57	const MOODS = {
58	  friendly: `Your manner: warm and encouraging. You may start with a few words that echo something specific they said.`,
59	  neutral: `Your manner: calm and professional. You may start with "Okay." or "Got it." and nothing more.`,
60	  tough: `Your manner: direct and sceptical, like a demanding hiring manager. No praise, no softening. Get straight to the question.`,
61	};
62	const persona = (mood, name = 'Rahul', role = 'junior frontend developer') => `You are Ananya, a senior engineer interviewing ${name} for a ${role} role. This is a spoken mock interview: every word you write is read aloud.
63	
64	How you speak:
65	- Like a real person across the table: plain, natural spoken English. Contractions are fine.
66	- At most two short sentences, under 30 words in total.
67	- No quotation marks, no markdown, no lists, no emojis.
68	- Never say "good start", "great answer" or similar praise. Never teach, never answer for them, never give feedback.
69	
70	${MOODS[mood]}`;
71	
72	const ANGLES = {
73	  expand: 'The answer was very short. Ask them to walk you through it in more detail.',
74	  ownership: 'They kept saying "we". Ask what they personally did, as opposed to the team.',
75	  outcome: 'They never said how it turned out. Ask for the result, ideally a number or something measurable.',
76	  specifics: 'The answer was vague. Ask for the concrete steps they took.',
77	  deeper: 'The answer was complete. Ask one deeper question: a trade-off they made, or how they knew it worked.',
78	  edgecase: 'Ask a "what happens if" question about an edge case of what they explained.',
79	  motivation: 'Ask what they are looking for in their next role.',
80	};
81	
82	// Multi-turn: the model plays the interviewer's next turn; the angle rides along
83	// as a note on the candidate's turn. A single instruction block made a 1B model
84	// re-enact the transcript instead.
85	const guidedFollowUp = (mood, q, a, angle) => [
86	  { role: 'user', content: `${persona(mood)}\n\nRahul has just sat down. Ask your first question.` },
87	  { role: 'assistant', content: q },
88	  { role: 'user', content: `${a}\n\n[Note for Ananya, not said aloud: ${ANGLES[angle]} Refer to one detail he said. One question, under 30 words.]` },
89	];
90	
91	const reaction = (mood, a) => [{ role: 'user', content: `${persona(mood)}\n\nRahul just answered: ${a}
92	
93	You are moving on to the next topic. Say one short sentence, under 10 words, that closes this topic, like "Thanks, that's clear." or "Okay, let's move on." Do not ask anything.
94	Write only the words you say out loud.` }];
95	
96	const tip = (q, a, facts) => [{ role: 'user', content: `An interview candidate answered a practice question.
97	Measured by software: ${facts}
98	Question: "${q}"
99	Answer: "${a}"
100	
101	Write one specific tip to improve this answer, addressed to the candidate as "you", in one sentence under 30 words. Point at something they actually said or left out. Write only the tip.` }];
102	
103	const starJudge = (a) => [{ role: 'user', content: `Judge this interview answer with the STAR method. Reply with JSON only, no other text, in this shape:
104	{"situation": true/false, "task": true/false, "action": true/false, "result": true/false, "tip": "one sentence"}
105	A part is true only if the answer clearly states it.
106	
107	Answer: "${a}"` }];
108	
109	const codeReview = (problem, code) => [{ role: 'user', content: `You are a coding interviewer. Problem: "${problem}"
110	Candidate's pseudo-code:
111	${code}
112	
113	Is it correct? Reply in this shape:
114	Verdict: correct or incorrect
115	Bug: the bug in one sentence, or none
116	Edge cases: one sentence` }];
117	
118	// Guard: what the app does to every interviewer line before it is spoken.
119	// Returns null when the line is unusable and a written fallback should be used.
120	const guard = (text, asked = '', answer = '', mustAsk = true) => {
121	  const norm = (s) => s.toLowerCase().replace(/[^a-z ]/g, '').trim();
122	  const t = text.replace(/[“”"*_#\[\]]/g, '').replace(/\s+/g, ' ').trim();
123	  let ss = (t.match(/[^.!?]+[.!?]+/g) ?? [t]).map((s) => s.trim())
124	    .filter((s) => !/good start|good example|great answer|excellent|amazing|let.s start/i.test(s))
125	    .filter((s) => norm(s) !== norm(asked) && !(answer && norm(answer).includes(norm(s))));
126	  if (!mustAsk) {
127	    ss = ss.filter((s) => !s.endsWith('?')).slice(0, 1);
128	    return ss.length ? ss[0] : null;
129	  }
130	  const qi = ss.findIndex((s) => s.endsWith('?'));
131	  return qi === -1 ? null : ss.slice(Math.max(0, qi - 1), qi + 1).join(' ');
132	};
133	
134	// ---------------------------------------------------------------------------
135	// Suites. `expect` is what a human grader looks for; it is not auto-scored.
136	// ---------------------------------------------------------------------------
137	const baseline = [
138	  { name: 'opening question', max: 128, messages: [
139	    { role: 'system', content: 'You are Riya, a friendly but sharp interviewer for a junior frontend developer role. Ask exactly ONE question at a time, under 40 words, spoken aloud, no lists or markdown.' },
140	    { role: 'user', content: 'Hi, I am ready. Interview type: behavioural.' }], expect: 'One behavioural question.' },
141	  { name: 'STAR judge: rambling answer', max: 160, messages: starJudge(A.rambling), expect: 'situation true (internship, broken build), task/action weak, result false. Valid JSON with booleans.' },
142	  { name: 'STAR judge: strong answer', max: 160, messages: starJudge(A.starGood), expect: 'All four true. Valid JSON with booleans.' },
143	  { name: 'questions from a job description', max: 200, messages: [{ role: 'user', content: `Job description: "Junior Frontend Engineer. React, TypeScript, REST APIs, writing tests with Jest, working with designers in Figma. You will build dashboards for logistics customers."
144	Write 4 interview questions for this role, one per line, no numbering, each under 25 words. Mix 2 technical and 2 behavioural.` }], expect: '4 relevant questions, one per line.' },
145	  { name: 'code review: off-by-one', max: 200, messages: codeReview('Return the largest number in a list.', `max = list[0]
146	for i from 1 to length(list) - 2:
147	    if list[i] > max: max = list[i]
148	return max`), expect: 'Incorrect: the loop stops one early and never checks the last element. Empty list not handled.' },
149	  { name: 'code review: correct palindrome', max: 200, messages: codeReview('Return true if a string is a palindrome.', `left = 0, right = length(s) - 1
150	while left < right:
151	    if s[left] != s[right]: return false
152	    left = left + 1; right = right - 1
153	return true`), expect: 'Correct, no bug. Empty string returns true, which is fine.' },
154	];
155	
156	const guided = [];
157	for (const [mood, q, a, angle] of [
158	  ['friendly', Q.pressure, A.rambling, 'specifics'], ['neutral', Q.pressure, A.rambling, 'outcome'], ['tough', Q.pressure, A.rambling, 'specifics'],
159	  ['friendly', Q.improved, A.we, 'ownership'], ['neutral', Q.improved, A.we, 'ownership'], ['tough', Q.improved, A.we, 'ownership'],
160	  ['neutral', Q.improved, A.starGood, 'deeper'], ['tough', Q.improved, A.starGood, 'deeper'],
161	  ['friendly', Q.pressure, A.short, 'expand'], ['tough', Q.pressure, A.short, 'expand'],
162	  ['neutral', Q.useEffect, A.techPartial, 'edgecase'], ['tough', Q.leaving, A.hr, 'motivation'],
163	]) {
164	  guided.push({ name: `follow-up / ${mood} / ${angle}`, max: 60, messages: guidedFollowUp(mood, q, a, angle),
165	    post: (raw) => guard(raw, q, a, true), expect: `One question that does: ${ANGLES[angle]}` });
166	}
167	for (const [mood, a] of [['friendly', A.starGood], ['tough', A.rambling], ['neutral', A.we]]) {
168	  guided.push({ name: `reaction / ${mood}`, max: 30, messages: reaction(mood, a),
169	    post: (raw) => guard(raw, '', '', false), expect: 'One short closing sentence, no question, no praise.' });
170	}
171	guided.push({ name: 'tip / rambling', max: 80, messages: tip(Q.pressure, A.rambling, '38 seconds, 9 filler words, 171 words per minute, STAR parts missing: task, result'), expect: 'Specific, actionable, addressed as "you".' });
172	guided.push({ name: 'tip / "we" answer', max: 80, messages: tip(Q.improved, A.we, '41 seconds, 1 filler word, 140 words per minute, STAR parts missing: task'), expect: 'Mentions personal role or a number.' });
173	guided.push({ name: 'tip / HR', max: 80, messages: tip(Q.leaving, A.hr, '12 seconds, 0 filler words, 150 words per minute'), expect: 'Suggests positive framing.' });
174	
175	const suites = { baseline, guided, all: [...baseline, ...guided] };
176	
177	// ---------------------------------------------------------------------------
178	// Run.
179	// ---------------------------------------------------------------------------
180	try {
181	  if (!navigator.gpu) throw new Error('No WebGPU in this browser');
182	  status(`loading ${MODEL} (${DTYPE})`);
183	  const t0 = performance.now();
184	  let lastPct = -1;
185	  const gen = await pipeline('text-generation', MODEL, {
186	    device: 'webgpu', dtype: DTYPE,
187	    progress_callback: (p) => {
188	      if (p.status === 'progress' && /onnx_data/.test(p.file ?? '')) {
189	        const pct = Math.floor(p.progress);
190	        if (pct !== lastPct) { lastPct = pct; status(`downloading ${p.file}: ${pct}%`); }
191	      }
192	    },
193	  });
194	  window.loadSeconds = +((performance.now() - t0) / 1000).toFixed(1);
195	
196	  const cases = suites[SUITE];
197	  for (const [i, c] of cases.entries()) {
198	    status(`running ${i + 1}/${cases.length}: ${c.name}`);
199	    const s = performance.now();
200	    const res = await gen(c.messages, { max_new_tokens: c.max, do_sample: false });
201	    const raw = res[0].generated_text.at(-1).content.trim();
202	    const ms = Math.round(performance.now() - s);
203	    const tokens = gen.tokenizer.encode(raw).length;
204	    const spoken = c.post ? c.post(raw) : undefined;
205	    window.results.push({ name: c.name, ms, tokens, raw, spoken, expect: c.expect });
206	    out.insertAdjacentHTML('beforeend', `<h3></h3><p class="meta"></p><pre></pre>`);
207	    const [h, meta, pre] = [...out.children].slice(-3);
208	    h.textContent = c.name;
209	    meta.textContent = `${ms} ms, ${tokens} tokens. Expect: ${c.expect}`;
210	    pre.textContent = c.post ? `RAW: ${raw}\nSPOKEN: ${spoken ?? '(written fallback)'}` : raw;
211	  }
212	  status(`done: ${MODEL} (${DTYPE}), load ${window.loadSeconds} s`);
213	
214	  const btn = document.getElementById('save');
215	  btn.disabled = false;
216	  btn.onclick = () => {
217	    const blob = new Blob([JSON.stringify({ model: MODEL, dtype: DTYPE, loadSeconds: window.loadSeconds, results: window.results }, null, 2)], { type: 'application/json' });
218	    const a = document.createElement('a');
219	    a.href = URL.createObjectURL(blob);
220	    a.download = `${MODEL.split('/').pop()}-${DTYPE}.json`;
221	    a.click();
222	  };
223	} catch (e) {
224	  status('error: ' + (e?.message || e));
225	}
226	</script>
227	</body>
228	</html>
